//! 🎟️ Checks the exact original retained identity and receipt at the host component boundary.
use super::wit_reactor;
use semio_plugin_guest_contract::{PluginHostError, TurnFault};
use semio_framework::kernel::{RetainedTurnInput,RetainedTurnReceipt};
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress};
#[path="💼️jobs/🦀️.rs"]
pub mod jobs;
pub fn input_to_wit(input:RetainedTurnInput)->wit_reactor::RetainedTurnInput{wit_reactor::RetainedTurnInput{operation:input.operation,generation:input.generation,epoch:input.epoch,work:wit_reactor::OriginalActorTurnWork{clock_binding:input.work.clock_binding,absolute_deadline_us:input.work.absolute_deadline_us,fuel:input.work.fuel},grant:grant_to_wit(input.grant)}}
pub fn grant_to_wit(grant:RetainedCloneGrant)->wit_reactor::RetainedGrant{wit_reactor::RetainedGrant{maximum_items:grant.maximum_items as u64,maximum_copy_bytes:grant.maximum_copy_bytes as u64,maximum_capacity_bytes:grant.maximum_capacity_bytes as u64,maximum_release_bytes:grant.maximum_release_bytes as u64,maximum_depth:grant.maximum_depth as u64}}
fn extent(value:u64)->Result<usize,TurnFault>{usize::try_from(value).map_err(|_|fault("retained component extent exceeds original native address space"))}
fn grant_from_wit(grant:wit_reactor::RetainedGrant)->Result<RetainedCloneGrant,TurnFault>{Ok(RetainedCloneGrant{maximum_items:extent(grant.maximum_items)?,maximum_copy_bytes:extent(grant.maximum_copy_bytes)?,maximum_capacity_bytes:extent(grant.maximum_capacity_bytes)?,maximum_release_bytes:extent(grant.maximum_release_bytes)?,maximum_depth:extent(grant.maximum_depth)?})}
pub fn receipt_from_wit(receipt:wit_reactor::RetainedTurnReceipt,original:RetainedTurnInput)->Result<RetainedTurnReceipt,TurnFault>{let input=RetainedTurnInput{operation:receipt.input.operation,generation:receipt.input.generation,epoch:receipt.input.epoch,work:semio_framework_actor::OriginalActorTurnWork{clock_binding:receipt.input.work.clock_binding,absolute_deadline_us:receipt.input.work.absolute_deadline_us,fuel:receipt.input.work.fuel},grant:grant_from_wit(receipt.input.grant)?};let spent=RetainedCloneProgress{copied_items:extent(receipt.spent.copied_items)?,copied_bytes:extent(receipt.spent.copied_bytes)?,retained_capacity_bytes:extent(receipt.spent.retained_capacity_bytes)?,released_bytes:extent(receipt.spent.released_bytes)?};let receipt=RetainedTurnReceipt{input,spent,work_units_spent:receipt.work_units_spent,remaining:grant_from_wit(receipt.remaining)?,remaining_fuel:receipt.remaining_fuel};receipt.validate_for(original).map_err(|_|fault("returned retained component receipt does not conserve its original supplied identity and currencies"))?;Ok(receipt)}
fn fault(message:&'static str)->TurnFault{TurnFault::Host(PluginHostError::Plugin(message.to_string()))}
fn input_from_wit(input:wit_reactor::RetainedTurnInput)->Result<RetainedTurnInput,TurnFault>{Ok(RetainedTurnInput{operation:input.operation,generation:input.generation,epoch:input.epoch,work:semio_framework_actor::OriginalActorTurnWork{clock_binding:input.work.clock_binding,absolute_deadline_us:input.work.absolute_deadline_us,fuel:input.work.fuel},grant:grant_from_wit(input.grant)?})}
fn progress_from_wit(spent:wit_reactor::RetainedProgress)->Result<RetainedCloneProgress,TurnFault>{Ok(RetainedCloneProgress{copied_items:extent(spent.copied_items)?,copied_bytes:extent(spent.copied_bytes)?,retained_capacity_bytes:extent(spent.retained_capacity_bytes)?,released_bytes:extent(spent.released_bytes)?})}
fn cause_from_wit(cause:wit_reactor::ActorAuthorityRefusal)->semio_framework_value::ValueRefusalKind{use semio_framework_value::ValueRefusalKind as Native;use wit_reactor::ActorAuthorityRefusal as Wire;match cause{Wire::InvalidValue=>Native::InvalidValue,Wire::Canceled=>Native::Canceled,Wire::OwnershipLimit=>Native::OwnershipLimit,Wire::AllocationFailed=>Native::AllocationFailed,Wire::WorkLimit=>Native::WorkLimit,Wire::DepthLimit=>Native::DepthLimit,Wire::UnsupportedOwner=>Native::UnsupportedOwner,Wire::InvariantViolated=>Native::InvariantViolated}}
/// 🌱️ Returns the raw admission tuple before any Host readiness or receipt validation.
pub fn admission_from_wit(call:wit_reactor::ActorAdmissionCall)->Result<semio_framework_actor::retained_context::OriginalActorAdmissionReply,TurnFault>{Ok(semio_framework_actor::retained_context::OriginalActorAdmissionReply{input:input_from_wit(call.input)?,spent:progress_from_wit(call.spent)?,work_units_spent:call.work_units_spent,ready:call.ready,refusal:call.refusal.map(cause_from_wit)})}
/// 📥️ An unmappable raw ingress keeps its actual returned vector beside the conversion refusal.
pub fn input_admission_from_wit(call:wit_reactor::ActorInputAdmissionCall)->Result<semio_framework_actor::retained_context::OriginalActorInputAdmissionReply,(TurnFault,wit_reactor::ActorInputAdmissionCall)>{
 use semio_framework_actor::retained_context::{OriginalActorInputDisposition as Native,OriginalActorInputAdmissionReply};
 let converted=(||Ok::<_,TurnFault>((RetainedTurnInput{operation:call.input.operation,generation:call.input.generation,epoch:call.input.epoch,work:semio_framework_actor::OriginalActorTurnWork{clock_binding:call.input.work.clock_binding,absolute_deadline_us:call.input.work.absolute_deadline_us,fuel:call.input.work.fuel},grant:RetainedCloneGrant{maximum_items:extent(call.input.grant.maximum_items)?,maximum_copy_bytes:extent(call.input.grant.maximum_copy_bytes)?,maximum_capacity_bytes:extent(call.input.grant.maximum_capacity_bytes)?,maximum_release_bytes:extent(call.input.grant.maximum_release_bytes)?,maximum_depth:extent(call.input.grant.maximum_depth)?}},RetainedCloneProgress{copied_items:extent(call.spent.copied_items)?,copied_bytes:extent(call.spent.copied_bytes)?,retained_capacity_bytes:extent(call.spent.retained_capacity_bytes)?,released_bytes:extent(call.spent.released_bytes)?})))();
 let(input,spent)=match converted{Ok(original)=>original,Err(error)=>return Err((error,call))};
 let disposition=match call.disposition{wit_reactor::ActorInputDisposition::Borrowed=>Native::Borrowed,wit_reactor::ActorInputDisposition::Retained=>Native::Retained,wit_reactor::ActorInputDisposition::Returned=>Native::Returned};
 Ok(OriginalActorInputAdmissionReply{input,spent,work_units_spent:call.work_units_spent,ready:call.ready,disposition,returned_wire:call.returned_wire,refusal:call.refusal.map(cause_from_wit)})
}
/// ♻️ A blocked or refused close keeps its exact actual child delta in the required receiving ABI.
pub fn close_from_wit(call:wit_reactor::ActorContextCloseCall)->Result<semio_framework_actor::retained_context::OriginalActorCloseReply,TurnFault>{Ok(semio_framework_actor::retained_context::OriginalActorCloseReply{input:input_from_wit(call.input)?,spent:progress_from_wit(call.spent)?,work_units_spent:call.work_units_spent,complete:call.complete,blocked:call.blocked,refusal:call.refusal.map(cause_from_wit)})}
/// 🧾️ Semantic failure is a scalar marker while the same typed Fault remains in guest custody.
pub fn failure_from_wit(call:wit_reactor::ActorCallRefusal)->TurnFault{let original=(||Ok::<_,TurnFault>(semio_plugin_guest_contract::original_actor_context::OriginalActorFixedCall{input:input_from_wit(call.input)?,spent:progress_from_wit(call.spent)?,work_units_spent:call.work_units_spent,kind:semio_plugin_guest_contract::original_actor_context::OriginalActorFixedKind::Failure{authority:match call.failure{wit_reactor::ActorCallFailure::Authority(cause)=>Some(cause_from_wit(cause)),wit_reactor::ActorCallFailure::Semantic=>None}}}))();match original{Ok(call)=>TurnFault::ActorCall(call),Err(error)=>error}}
#[cfg(test)]
mod input_tests{
 use super::*;
 #[test]
 fn wit_actor_input_returns_its_same_vector_even_when_disposition_is_malformed(){
  for disposition in[wit_reactor::ActorInputDisposition::Borrowed,wit_reactor::ActorInputDisposition::Retained,wit_reactor::ActorInputDisposition::Returned]{let wire=vec![0,1,255];let pointer=wire.as_ptr();let returned=matches!(&disposition,wit_reactor::ActorInputDisposition::Returned);let input=RetainedTurnInput{operation:1,generation:1,epoch:1,work:semio_framework_actor::OriginalActorTurnWork{clock_binding:1,absolute_deadline_us:1,fuel:1},grant:Default::default()};let call=wit_reactor::ActorInputAdmissionCall{input:input_to_wit(input),spent:wit_reactor::RetainedProgress{copied_items:0,copied_bytes:0,retained_capacity_bytes:0,released_bytes:0},work_units_spent:0,ready:true,disposition,returned_wire:Some(wire),refusal:Some(wit_reactor::ActorAuthorityRefusal::InvalidValue)};let reply=match input_admission_from_wit(call){Ok(reply)=>reply,Err(_)=>panic!("native-addressable raw WIT reply maps without replacing its wire")};assert_eq!(reply.returned_wire.as_ref().unwrap().as_ptr(),pointer);assert_eq!(reply.returned_wire.as_deref(),Some(&[0,1,255][..]));assert_eq!(reply.disposition_is_well_formed(),returned);assert!(reply.ready);assert_eq!(reply.refusal,Some(semio_framework_value::ValueRefusalKind::InvalidValue));}
 }
}